/* Supplied horizontal SZABIST logo; source pixels and proportions are unchanged. */
const logo = "data:image/png;base64,";
export function szabistBackLogo(x,y,width,height) {
  return '<svg x="'+x+'" y="'+y+'" width="'+width+'" height="'+height+'" viewBox="231 140 1224 357" preserveAspectRatio="xMidYMid meet"><image href="'+logo+'" width="1640" height="924"/></svg>';
}
